<?phpnamespace app\api\model;use app\common\model\Order as OrderModel;use hema\wechat\Pay as WxPay;use hema\alipay\Driver as AlipayPay;use hema\wechat\Wechat;use think\facade\Cache;use think\facade\Db;/** * 订单模型 */class Order extends OrderModel{    /**     * 隐藏字段     */    protected $hidden = [];    /**     * 订单确认-购物车结算     */    public function getCart($order_mode,$user_id)    {        $model = new Cart($user_id);        return $model->getList($order_mode);    }    /**     * 新增订单     */    public function add(array $order,$coupon_user_id)    {		$order['order_no'] = order_no();		$order['activity_price'] = $order['activity_price'] + $order['vip_price'];//卡券优惠+会员优惠		$order['total_price'] = $order['order_total_price'];//订单商品金额		$order['pay_price'] = $order['order_pay_price'];	//实付金额				// 订单商品列表		$goodsList = [];		foreach ($order['goods_list'] as $goods) {    		/* @var Goods $goods */    		$goodsList[] = [    			'user_id' => $order['user_id'],    			'goods_id' => $goods['goods_id'],    			'goods_name' => $goods['goods_name'],    			'image_id' => isset($goods['goods_sku']['image']['url'])?$goods['goods_sku']['image_id']:$goods['image_id'],    			'spec_type' => $goods['spec_type'],    			'spec_sku_id' => $goods['goods_sku']['spec_sku_id'],    			'goods_spec_id' => $goods['goods_sku']['goods_spec_id'],    			'goods_attr' => $goods['goods_sku']['goods_attr'],    			'goods_price' => $goods['goods_sku']['goods_price'],    			'line_price' => $goods['goods_sku']['line_price'],    			'total_num' => $goods['total_num'],    			'total_price' => $goods['total_price'],    		];		}		if(sizeof($goodsList) == 0){		    $this->error = '下单商品不可为空';            return false;		}			// 开启事务        Db::startTrans();        try {            //核销优惠券            if($coupon_user_id > 0){                $coupon = CouponUser::get($coupon_user_id,['coupon']);//获取要核销的优惠券                //判断是否是满赠券                if($coupon['type']['value'] == 30){                    $add_coupon = [];                    $model = new CouponUser;                    foreach ($coupon['coupon']['gift'] as $item){                        if(isset($item['coupon_id'])){                            $add_coupon[] = $model->dateTmp($item,$order['user_id']);                        }else{                            $goodsList[] = [                    			'user_id' => $order['user_id'],                    			'goods_id' => $item['goods_id'],                    			'goods_name' => $item['goods_name'],                    			'image_id' => $item['image_id'],                    			'spec_type' => $item['spec_type'],                    			'total_num' => 1,                    			'is_gift' => 1,//是否赠送                    		];                        }                    }                    //判断是否有赠送优惠券                    if(sizeof($add_coupon) > 0){                        $model->saveAll($add_coupon);//添加多条记录                    }                }                $coupon->save(['status' => 20]);//核销优惠券            }                        // 记录订单信息			$this->save($order);			// 保存订单商品信息			$this->goods()->saveAll($goodsList);			//如果是外卖,记录收货地址			if($order['order_mode']==20){				$this->address()->save([					'user_id' => $order['user_id'],					'name' => $order['address']['name'],					'gender' => $order['address']['gender']['value'],					'phone' => $order['address']['phone'],					'location' => $order['address']['location'],					'province' => $order['address']['province'],					'city' => $order['address']['city'],					'district' => $order['address']['district'],					'detail' => $order['address']['detail'],				]);			}			Db::commit();            return true;        } catch (\Exception $e) {            Db::rollback();        }        return false;    }    /**     * 用户支付     * $order_no = 第二次支付会传递该参数     * $browser 浏览器类型，只有H5才会传递     */    public function userPay($pay_mode,$mp,$browser='',$order_no='')    {        // 发起微信支付        if($pay_mode==1){            if(!empty($order_no)){                $this->order_no = $order_no;                $this->save();            }else{               $order_no = $this->order_no;             }            //获取小程序配置的支付参数            $wxpay = new WxPay;            //网页其它浏览器平台支付接口            if($mp == 'h5' and $browser == 'other'){                if(!$result = $wxpay->h5($order_no,$this->pay_price,'api/notify/order','订单支付')){                    $this->error = $wxpay->getError();                    return false;                }            }            //微信小程序或微信浏览器支付接口            if($mp == 'weixin' or ($mp == 'h5' and $browser == 'weixin')){                if(!$result = $wxpay->jsapi($order_no,$this->pay_price,$this->user['open_id'],'api/notify/order','订单支付')){                    $this->error = $wxpay->getError();                    return false;                }            }            return [                'payment' => $result,                'order_id' => $this->order_id            ];        }        //支付宝小程序支付        if($pay_mode == 4){            if(!empty($order_no)){                $this->order_no = $order_no;                $this->save();            }else{               $order_no = $this->order_no;             }            //非微信浏览器支付接口            if($mp == 'h5' and $browser != 'weixin'){                $alipay = new AlipayPay('aliweb');                if(!$result = $alipay->tradeWapPay($order_no,$this->pay_price,'api/notify/order/mode/aliweb','h5/#/pages/order/detail?id='.$this->order_id,'订单支付')){                    $this->error = $alipay->getError();                    return false;                }            }            //支付宝小程序支付接口            if($mp == 'alipay'){                $alipay = new AlipayPay('aliapp');                if(!$result = $alipay->tradeCreate($order_no,$this->pay_price,$this->user['alipay_open_id'],'api/notify/order/mode/aliapp','订单支付')){                    $this->error = $alipay->getError();                    return false;                }            }            return [                'payment' => $result,                'order_id' => $this->order_id            ];        }                // 开启事务        Db::startTrans();        try {            			//发起余额支付            if($pay_mode==2){                //获取用户信息                $user = User::get($this->user_id);                if($user['money'] < $this->pay_price){                    $this->error = '余额不足！';                    return false;                }                $user->money = ['dec',$this->pay_price];//扣除余额                $user->pay = ['inc', $this->pay_price];//增加消费金额                //开通会员才有积分                if($user['v']['value'] > 0){                    $score = intval($this->pay_price);                    $user->score = ['inc', $score];//增加消费积分                }                $user->save();//保存更改                $this->pay_mode = 2;// 余额支付                $this->pay_status = 20;// 支付状态            }            $this->pay_time = time();//付款时间            $this->save();                         //避免：餐后支付下的订单，进行线上支付时重复执行下列操作操作            if(empty($order_no)){                $this->successOrder();            }        			Db::commit();            return [                'order_id' => $this->order_id            ];        } catch (\Exception $e) {            Db::rollback();        }        return false;    }        /**     * 待支付订单详情 - 支付回调     */    public function payDetail($order_no)    {        return self::with(['goods','table','address'])->where(['order_no' => $order_no, 'pay_status' => 10])->find();    }    /**     * 更新付款状态 - 支付回调     */    public function updatePayStatus($mp,$transaction_id)    {		if($this['pay_status']['value']==20){			//避免重复回调			return true;		}				// 开启事务        Db::startTrans();        try {    		//更新用户信息    		$user = User::get($this->user_id);    		$user->pay = ['inc', $this->pay_price];//增加消费金额    		//开通会员才有积分    		if($user['v']['value'] > 0){    		    $score = intval($this->pay_price);                $user->score = ['inc', $score];//增加消费积分            }    		$user->save();    		    		if($mp == 'weixin'){    		    $pay_mode = 1;//微信    		}else{    		    $pay_mode = 4;//支付宝    		}    		// 更新订单状态    		$this->save([    		    'pay_mode' => $pay_mode,//支付方式    			'pay_status' => 20,    			'pay_time' => time(),    			'transaction_id' => $transaction_id,    		]);    		$model = OrderModel::get($this->order_id, ['goods','table','address']);    		$model->successOrder();//成功下单的操作            Db::commit();            return true;        } catch (\Exception $e) {            Db::rollback();        }        return false;    }        /**     * 退款订单     */    public function userRefund(array $data)	{		$order = Cache::get('refund_' . $this->order_id);//获取退款订单数据		$goods = [];//修改订单商品表		if($data['mode']==1){			//全单退			$order['refund_price'] = $this->pay_price;			for($n=0;$n<sizeof($order['goods']);$n++){                $order['goods'][$n]['refund_num'] = $order['goods'][$n]['total_num'];                $order['goods'][$n]['refund_price'] = $order['goods'][$n]['total_price'];				$goods[] = [				    'order_goods_id' => $order['goods'][$n]['order_goods_id'],				    'refund_num' => $order['goods'][$n]['refund_num'],				    'refund_price' => $order['goods'][$n]['refund_price'],				];			}		}else{			//部分退			for($n=0;$n<sizeof($order['goods']);$n++){			    if($order['goods'][$n]['refund_num'] > 0){			        $goods[] = [    				    'order_goods_id' => $order['goods'][$n]['order_goods_id'],    				    'refund_num' => $order['goods'][$n]['refund_num'],    				    'refund_price' => $order['goods'][$n]['refund_price'],    				];			    }			}		}		// 开启事务        Db::startTrans();        try {			$this->save([				'refund_price'  => $order['refund_price'],//退款金额				'refund_desc'  => $data['desc'],//退款理由				'order_status' => 40,//退款状态				'refund_time' => time(),//退款时间			]);            foreach ($goods as $item) {                OrderGoods::where('order_goods_id',$item['order_goods_id'])->update($item);            }			Db::commit();            $order['refund_desc'] = $data['desc'];//补充退款理由            Device::print($order,1);//打印退款商品订单            			//用户申请退款通知			$openIds = ShopClerk::where('wx_open_id','<>','')			    ->column('wx_open_id');    		//批量发送模板消息 - 使用公众号    		$wx = new Wechat;    		foreach($openIds as $item){    		    $wx->sendApplyRefund($item,$this->order_no,$order['refund_price']);    		}            return true;        } catch (\Exception $e) {            Db::rollback();        }        return false;	}    /**     * 待退款订单详情 - 微信退款回调     */    public function refundDetail($order_no)    {		return self::get(['order_no' => $order_no, 'order_status' => 40, 'refund_status' => 30], ['goods']);    }	/**     * 更新退款款状态 - 微信退款回调     */    public function updateRefundStatus($refund_id)    {		if(!empty($this->refund_id)){			//避免重复回调			return true;		}		$this->refundCallback();//退款成功回调		return true;    }    /**     * 更新第三方配送状态     */    public function updateDeliveryStatus($data,$mode)    {		if($mode == 'dada'){			//待接单＝1,待取货＝2,配送中＝3,已完成＝4,已取消＝5, 指派单=8,妥投异常之物品返回中=9, 妥投异常之物品返回完成=10, 骑士到店=100,创建达达运单失败=1000			switch ((string)$data['order_status']) {	            case '2': //已接单 - 骑手正赶往商家					$dev = [						'delivery_status' => 20,						'linkman' => $data['dm_name'],						'phone' => $data['dm_mobile']					];	                break;	            case '100': //已到店 - 骑手已到店					$dev = [						'delivery_status' => 30					];	                break;	            case '3': //已取件 - 骑手开始配送					$dev = [						'delivery_status' => 40					];	                break;	            case '4';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case '5': //订单被取消					$this->save([					    'delivery_status' => 10					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}		if($mode == 'sf'){			switch ((string)$data['order_status']) {	            case '10': //已接单 - 骑手正赶往商家					$dev = [						'delivery_status' => 20,						'linkman' => $data['operator_name'],						'phone' => $data['operator_phone']					];	                break;	            case '12': //到店 - 骑手已到店					$dev = [						'delivery_status' => 30					];	                break;	            case '15': //已取件 - 骑手开始配送					$dev = [						'delivery_status' => 40					];	                break;	            case '17';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case '22': //订单被取消 - 配送员撤单					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            case '2': //订单被取消 - 顺丰原因					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}		if($mode == 'uu'){			//当前状态1下单成功 3跑男抢单 4已到达 5已取件 6到达目的地 10收件人已收货 -1订单取消			switch ((string)$data['state']) {	            case '3': //已接单 - 骑手正赶往商家					$dev = [						'delivery_status' => 20,						'linkman' => $data['driver_name'],						'phone' => $data['driver_mobile']					];	                break;	            case '4': //已到店 - 骑手已到店					$dev = [						'delivery_status' => 30					];	                break;	            case '5': //已取件 - 骑手开始配送					$dev = [						'delivery_status' => 40					];	                break;	            case '6';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case '-1': //订单被取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            case '-2': //客服取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            case '-3': //超时无人接单取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}		if($mode == 'make'){			//loading = 待付款', cancel='订单已取消', payed='待接单',wait_to_shop='待到店', accepted='待取件', geted='待收件',gotoed= '待评价', completed='订单已完成');			switch ($data['status']) {	            case 'accepted': //已接单 - 骑手正赶往商家					$dev = [						'delivery_status' => 20,						'linkman' => $data['rider_name'],						'phone' => $data['rider_mobile']					];	                break;	            case 'wait_to_shop': //已到店 - 骑手已到店					$dev = [						'delivery_status' => 30					];	                break;	            case 'geted': //已取件 - 骑手开始配送					$dev = [						'delivery_status' => 40					];	                break;	            case 'gotoed';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case 'payed': //订单被取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}		if($mode == 'shansong'){			switch ($data['status']) {	            case '30': //已接单	                if($data['subStatus']==1){	                   $dev = [    						'delivery_status' => 20,//待取货    						'linkman' => $data['rider_name'],    						'phone' => $data['rider_mobile']    					]; 	                }else{	                    $dev = [    						'delivery_status' => 30//已到店    					];	                }	                break;	            case '40': //已取件	                if($data['subStatus']==1){	                   $dev = [    						'delivery_status' => 40//骑手开始配送    					]; 	                }else{	                    return true;	                }	                break;	            case '50';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case '60': //订单被取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}		if($mode == 'hmpt'){			//当前状态1下单成功 3跑男抢单 4已到达 5已取件 6到达目的地 10收件人已收货 -1订单取消			switch ((string)$data['order_status']) {	            case '20': //已接单 - 骑手正赶往商家					$dev = [						'delivery_status' => 20,						'avatar' => $data['rider_avatar'],						'linkman' => $data['rider_name'],						'gender' => $data['rider_gender'],						'phone' => $data['rider_phone'],					];	                break;	            case '30': //已到店 - 骑手已到店					$dev = [						'delivery_status' => 30					];	                break;	            case '40': //已取件 - 骑手开始配送					$dev = [						'delivery_status' => 40					];	                break;	            case '50';//到达目的地 - 骑手已送达					$dev = [						'delivery_status' => 50,						'status' => 30					];					$this->save([						'delivery_status' => 30,						'delivery_time' => time()					]);	                break;	            case '60': //订单被取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            case '61': //订单被骑手取消					$this->save([						'delivery_status' => 10,					]);					OrderDelivery::where('order_id',$this->order_id)->delete();					return true;	                break;	            default:	            	return true;	        }		}    	$dev['delivery_time'] = time();		OrderDelivery::where('order_id',$this->order_id)->update($dev);		if($dev['delivery_status'] == 20){		    //骑手接单提醒            $this->sendMessage('horseman',$this->order_id);		}		if($dev['delivery_status'] == 40){		    //配送提醒            $this->sendMessage('delivery',$this->order_id);		}		return true;	}}